const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let p = 0;
const N = data[p++];
const K = data[p++];
const U = data[p++];

const cards = new Int32Array(N * K);
for (let i = 0; i < N * K; i++) {
    cards[i] = data[p++];
}

const pos = new Int32Array(U + 1);
for (let i = 1; i <= U; i++) {
    const num = data[p++];
    pos[num] = i;
}

let best = Infinity;
let winners = [];

for (let i = 0; i < N; i++) {
    let maxPos = 0;
    const base = i * K;

    for (let j = 0; j < K; j++) {
        const t = pos[cards[base + j]];
        if (t > maxPos) maxPos = t;
    }

    const id = i + 1;

    if (maxPos < best) {
        best = maxPos;
        winners = [id];
    } else if (maxPos === best) {
        winners.push(id);
    }
}

console.log(winners.join(' '));
